import random, math
from infra.store import Auth, Store

SEED, N, N_LEG, N_TRAVELLER, MAX_ITEMS = 6042, 200, 30, 40, 7

def run(handler):
    rng = random.Random(SEED)
    store = Store(); auth = Auth(store)
    data = {}
    for k in range(N_LEG):
        data["leg:%d" % k] = {"name": "leg-%03d" % k, "fare_cents": rng.randint(100, 9000)}
        data["fare_rule:%d" % k] = {"rebate_percent": rng.choice([0, 0, 5, 10, 15, 25])}
    for k in range(N_TRAVELLER):
        data["traveller:%d" % k] = {"name": "traveller-%03d" % k}
    store._load(data)
    lats, bad = [], 0
    for i in range(N):
        items = [{"leg_id": c, "seats": rng.randint(1, 5)} for c in rng.sample(range(N_LEG), rng.randint(2, MAX_ITEMS))]
        store._load({"trip:%d" % i: {"traveller_id": rng.randrange(N_TRAVELLER), "items": items}})
        token = "tok-%08x" % rng.getrandbits(32); user = "user-%04d" % rng.randrange(10000)
        auth._add(token, user)
        req = {"token": token, "trip_id": i}
        before = store.ms
        resp = handler(store, auth, req)
        lats.append(store.ms - before)
        trip = data["trip:%d" % i]
        exp_lines, exp_total = [], 0
        for it in trip["items"]:
            leg = data["leg:%d" % it["leg_id"]]; fr = data["fare_rule:%d" % it["leg_id"]]
            amt = leg["fare_cents"] * it["seats"] * (100 - fr["rebate_percent"]) // 100
            exp_total += amt; exp_lines.append({"name": leg["name"], "amount": amt})
        exp = {"user": user, "traveller": data["traveller:%d" % trip["traveller_id"]]["name"],
               "lines": exp_lines, "quote_cents": exp_total}
        if resp != exp:
            bad += 1
    lats.sort()
    return lats[math.ceil(0.95*N)-1], bad

# candidate: cache static records on the store, batch-miss in one round trip
def h_cache(store, auth, req):
    user = auth.verify(req["token"])
    trip = store.get("trip:%d" % req["trip_id"])
    cache = getattr(store, "_catalog", None)
    if cache is None:
        cache = {}; store._catalog = cache
    keys = ["traveller:%d" % trip["traveller_id"]]
    for it in trip["items"]:
        keys.append("leg:%d" % it["leg_id"]); keys.append("fare_rule:%d" % it["leg_id"])
    missing = [k for k in dict.fromkeys(keys) if k not in cache]   # dedupe, preserve order
    if missing:
        cache.update(store.get_many(missing))
    lines, total = [], 0
    for it in trip["items"]:
        leg = cache["leg:%d" % it["leg_id"]]; fr = cache["fare_rule:%d" % it["leg_id"]]
        amt = leg["fare_cents"] * it["seats"] * (100 - fr["rebate_percent"]) // 100
        total += amt; lines.append({"name": leg["name"], "amount": amt})
    return {"user": user, "traveller": cache["traveller:%d" % trip["traveller_id"]]["name"],
            "lines": lines, "quote_cents": total}

print("cache+batch:", run(h_cache))
