Auth, Store = store_mod.Auth, store_mod.Store

SEED, N_REQUESTS, N_PRODUCT, N_CUSTOMER, MAX_ITEMS = 1811, 200, 30, 40, 5

def build_load():
    rng = random.Random(SEED)
    store = Store(); auth = Auth(store)
    data = {}
    for k in range(N_PRODUCT):
        data["product:%d" % k] = {"name": "product-%03d" % k, "price_cents": rng.randint(100, 9000)}
        data["discount:%d" % k] = {"percent_off": rng.choice([0, 0, 5, 10, 15, 25])}
    for k in range(N_CUSTOMER):
        data["customer:%d" % k] = {"name": "customer-%03d" % k}
    store._load(data)
    orders = []
    for i in range(N_REQUESTS):
        items = [{"product_id": c, "quantity": rng.randint(1, 5)}
                 for c in rng.sample(range(N_PRODUCT), rng.randint(2, MAX_ITEMS))]
        order = {"customer_id": rng.randrange(N_CUSTOMER), "items": items}
        orders.append(order)
    return store, auth, orders

def p95(lat):
    lat = sorted(lat)
    return lat[math.ceil(0.95 * len(lat)) - 1]

# Strategy A: order get + single batched get_many(customer + all item product/discount), NO cache
def handleA(store, auth, order_id):
    # token handled externally for cost
    order = store.get("order:%d" % order_id)
    keys = ["customer:%d" % order["customer_id"]]
    for it in order["items"]:
        keys += ["product:%d" % it["product_id"], "discount:%d" % it["product_id"]]
    recs = store.get_many(keys)
    return recs

# Strategy B: order get + batched customer + batched items, WITH catalog cache (products/discounts)
def handleB(store, auth, order_id, cat_cache):
    order = store.get("order:%d" % order_id)
    # collect needed item keys not in cache
    needed = []
    for it in order["items"]:
        for prefix in ("product:", "discount:"):
            k = "%s%d" % (prefix, it["product_id"])
            if k not in cat_cache:
                needed.append(k)
    # customer
    ckey = "customer:%d" % order["customer_id"]
    batch = [ckey] + needed
    if batch:
        recs = store.get_many(batch)
        for k, v in recs.items():
            cat_cache[k] = v  # cache catalog keys (customer cached too if we choose)
    return recs

