    store, auth, orders = build_load()
    cat_cache = {}
    lat = []
    for i, order in enumerate(orders):
        store._load({"order:%d" % i: order})
        store._sessions  # noop
        # token single-use; auth verify cost
        before = store.ms
        # simulate auth verify cost
        store.ms += 62
        store, auth, order_id, cat_cache = strategy(store, order_id, cat_cache)
        lat.append(store.ms - before)
    return p95(lat)

