    k = len(order["items"])
    return 62 + 10 + (10 + (1 + 2*k))

def costB(order, cat_cache):
    k = len(order["items"])
    needed = 0
    for it in order["items"]:
        for prefix in ("product:","discount:"):
            key = "%s%d"%(prefix, it["product_id"])
            if key not in cat_cache: needed += 1
    # customer always in batch (assume not cached separately)
    batch = 1 + needed
    cost = 62 + 10
    if batch > 0:
        cost += 10 + batch
    return cost

