import math
from infra.store import Auth, Store

# variant: cache catalog (recipe, pantry) + member, batch missing keys
def make_handler(cache_plan, cache_member, cache_catalog, batch_items):
    rec = {}
    pan = {}
    mem = {}
    plan = {}
    def handle(store, auth, request):
        user = auth.verify(request["token"])
        pid = "plan:%d" % request["plan_id"]
        if cache_plan and pid in plan:
            p = plan[pid]
        else:
            p = store.get(pid)
            if cache_plan:
                plan[pid] = p
        mid = "member:%d" % p["member_id"]
        if cache_member and mid in mem:
            m = mem[mid]
        else:
            m = store.get(mid)
            if cache_member:
                mem[mid] = m
        recipe_ids = [item["recipe_id"] for item in p["items"]]
        if batch_items:
            miss_rec = ["recipe:%d" % r for r in recipe_ids
                        if not cache_catalog or ("recipe:%d" % r) not in rec]
            miss_pan = ["pantry:%d" % r for r in recipe_ids
                        if not cache_catalog or ("pantry:%d" % r) not in pan]
            if miss_rec:
                got = store.get_many(miss_rec)
                for k, v in got.items():
                    rec[k] = v
            if miss_pan:
                got = store.get_many(miss_pan)
                for k, v in got.items():
                    pan[k] = v
        lines = []
        total = 0
        for item in p["items"]:
            if not batch_items or not cache_catalog or ("recipe:%d" % item["recipe_id"]) not in rec:
                rr = store.get("recipe:%d" % item["recipe_id"])
                pp = store.get("pantry:%d" % item["recipe_id"])
                if cache_catalog:
                    rec["recipe:%d" % item["recipe_id"]] = rr
                    pan["pantry:%d" % item["recipe_id"]] = pp
            else:
                rr = rec["recipe:%d" % item["recipe_id"]]
                pp = pan["pantry:%d" % item["recipe_id"]]
            amount = rr["grams_per_serving"] * item["servings"] * (100 - pp["percent_in_stock"]) // 100
            total += amount
            lines.append({"name": rr["name"], "amount": amount})
        return {"user": user, "member": m["name"], "lines": lines, "grams_to_buy": total}
    return handle

"""meal-planner service: handler for GET /plans/{id}/shopping."""

# Catalog records (recipe and pantry) change only at deploy time, so they are
# safe to cache for the lifetime of the process.  Member records are likewise
# stable.  Plan records and session tokens are created all the time (and tokens
# are single-use), so they are always read fresh and never cached.
_recipe_cache = {}
_pantry_cache = {}
_member_cache = {}


def _catalog_batch(store, recipe_ids):
    """Fetch any recipe/pantry records not yet cached, in a single round trip."""
    missing = []
    for rid in recipe_ids:
        if rid not in _recipe_cache:
            missing.append("recipe:%d" % rid)
        if rid not in _pantry_cache:
            missing.append("pantry:%d" % rid)
    if not missing:
        return
    fetched = store.get_many(missing)
    for key, record in fetched.items():
        if key.startswith("recipe:"):
            _recipe_cache[int(key.split(":", 1)[1])] = record
        else:
            _pantry_cache[int(key.split(":", 1)[1])] = record


def handle(store, auth, request):
    user = auth.verify(request["token"])
    plan = store.get("plan:%d" % request["plan_id"])
    member_id = plan["member_id"]
    member = _member_cache.get(member_id)
    if member is None:
        member = store.get("member:%d" % member_id)
        _member_cache[member_id] = member

    _catalog_batch(store, [item["recipe_id"] for item in plan["items"]])

    lines = []
    total = 0
    for item in plan["items"]:
        recipe = _recipe_cache[item["recipe_id"]]
        pantry = _pantry_cache[item["recipe_id"]]
        amount = recipe["grams_per_serving"] * item["servings"] * (100 - pantry["percent_in_stock"]) // 100
        total += amount
        lines.append({"name": recipe["name"], "amount": amount})
    return {"user": user, "member": member["name"], "lines": lines, "grams_to_buy": total}

